<?php get_header(); while(have_posts()):the_post();$type=get_post_type();$opportunity=in_array($type,['nv_program','nv_scholarship','nv_internship','nv_job'],true); ?><section class="nv-content"><div class="nv-wrap nv-detail"><article><div class="nv-eyebrow"><?php $o=get_post_type_object($type);echo esc_html($o?$o->labels->singular_name:'NVConsult'); ?></div><h1><?php the_title(); ?></h1><?php $terms=get_the_terms(get_the_ID(),'nv_destination');if($terms&&!is_wp_error($terms)): ?><p class="nv-meta"><?php echo esc_html(implode(' · ',wp_list_pluck($terms,'name'))); ?></p><?php endif;if(has_post_thumbnail())the_post_thumbnail('large',['class'=>'nv-feature']); ?><div class="nv-prose"><?php the_content(); ?></div></article><?php if($opportunity): ?><aside class="nv-card nv-sticky"><h3><?php esc_html_e('Interested in this opportunity?','nvconsult'); ?></h3><p><?php esc_html_e('Start your application and manage the next steps through your NVConsult account.','nvconsult'); ?></p><a class="nv-btn nv-full" href="<?php echo esc_url(add_query_arg(['opportunity_id'=>get_the_ID(),'opportunity_type'=>$type],nvconsult_theme_url('apply'))); ?>"><?php esc_html_e('Start application','nvconsult'); ?></a><a class="nv-btn alt nv-full" href="<?php echo esc_url(nvconsult_theme_url('applicant-portal')); ?>"><?php esc_html_e('Applicant Portal','nvconsult'); ?></a></aside><?php endif; ?></div></section><?php endwhile;get_footer(); ?>
